#!/usr/bin/env sh
# fetch INSA / NASA (marego / MVB Magdeburger Verkehrsbetriebe) (DE) GTFS -> gtfs.zip. Regenerated by build_repo.py.
URL="https://reiseauskunft.insa.de/bin/stboard.exe/dn?L=vs_java3&input=Magdeburg+Alter+Markt&start=yes&maxJourneys=10&outputMode=tickerDataOnly"
DIR="$(CDPATH= cd "$(dirname "$0")" && pwd)"
echo "GET $URL"
curl -fSL --retry 3 --max-time 300 -o "$DIR/gtfs.zip" "$URL" || { echo "download failed"; exit 1; }
unzip -l "$DIR/gtfs.zip" 2>/dev/null | grep -q stops.txt || { echo "not valid GTFS (no stops.txt)"; exit 2; }
echo "ok: $DIR/gtfs.zip"
